def shuffle_digits(num):
    d = str(num)
    # Reorder the digits as 2nd, 4th, 1st, 3rd
    return int(d[1] + d[3] + d[0] + d[2])

import sys

PIECES = {"K": "King", "Q": "Queen", "R": "Rook",
          "B": "Bishop", "N": "Knight"}


def piece_names(move):
    move = move.rstrip("+#")  # drop check / checkmate markers
    if move in ("O-O", "O-O-O", "0-0", "0-0-0"):
        return ["King", "Rook"]
    if move[0] in PIECES:
        return [PIECES[move[0]]]
    return ["Pawn"]  # no initial -> pawn move


