def total_engagement(video: dict) -> int:
    return video["likes"] + video["comments"]


def engagement_rate(video: dict) -> float:
    if video["views"] == 0:
        return 0.0
    rate = (video["likes"] + video["comments"]) / video["views"] * 100
    return round(rate, 2)


def most_engaging_video(videos: list[dict]) -> str:
    best_title = None
    best_rate = None
    for v in videos:
        r = engagement_rate(v)
        if best_rate is None or r > best_rate:
            best_rate = r
            best_title = v["title"]
    return best_title


def videos_with_engagement_rate_above_threshold(videos: list[dict], threshold: float) -> list[str]:
    return [v["title"] for v in videos if engagement_rate(v) > threshold]


def average_engagement_rate(videos: list[dict]) -> float:
    rates = [engagement_rate(v) for v in videos if v["views"] != 0]
    if not rates:
        return 0.0
    return round(sum(rates) / len(rates), 2)

def point_position_relative_to_line(a, b, c, x, y) -> int:
    value = a * x + b * y + c
    if value > 0:
        return 1
    if value < 0:
        return -1
    return 0
